import{_ as c,o,c as d,a3 as a}from"./chunks/framework.DAK02U1-.js";const m=JSON.parse('{"title":"macOS","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"macOS | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/xclang/design/macos"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/xclang/design/macos"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/design/macos"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/design/macos"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/xclang/design/macos"}]]},"headers":[],"relativePath":"zh/xclang/design/macos.md","filePath":"zh/xclang/design/macos.md","lastUpdated":1794509097000}'),l={name:"zh/xclang/design/macos.md"};function i(t,e,n,s,r,p){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h1><p>本页介绍 xclang 的 macOS 目标平台、<code>xclang sdk fetch macos</code>、<code>ld64.lld</code> 以及 macOS 主机工具链是如何构建和配置的。如何为 macOS 目标平台编译程序见<a href="./../guide/cross-compiling#macos">交叉编译</a>。</p><h2 id="为什么使用-xclang-的-libc-而非系统自带版本" tabindex="-1">为什么使用 xclang 的 <code>libc++</code> 而非系统自带版本 <a class="header-anchor" href="#为什么使用-xclang-的-libc-而非系统自带版本" aria-label="Permalink to &quot;为什么使用 xclang 的 `libc++` 而非系统自带版本&quot;">​</a></h2><p>macOS 目标平台配置文件会将 xclang 的 <code>libc++</code> 头文件（<code>-stdlib++-isystem</code>）加入 C++ 头文件搜索路径，并把 xclang 的静态库 <code>libc++.a</code>（内含 <code>libc++abi</code>）排在 SDK 的 <code>libc++.tbd</code> 之前。栈展开库（unwinder）则使用系统 <code>libSystem</code> 自带的实现（<a href="./hermeticity">封闭性</a>）。</p><p>静态链接 xclang 的 <code>libc++</code> 有两个好处：</p><ul><li><strong>C++ 标准库特性不受操作系统版本限制</strong>：Apple 的 SDK 会为较新的 <code>libc++</code> 特性加上可用性属性（availability attribute），将其绑定到首次在 <code>/usr/lib/libc++.1.dylib</code> 中提供这些特性的 macOS 版本。将 xclang 的 <code>libc++</code> 链接进程序后，可用的标准库特性只取决于 xclang 版本，而不受目标 macOS 版本限制（例如对浮点数调用 <code>std::format</code> 在 <code>-mmacos-version-min=13.0</code> 下即可正常工作，而使用系统的 <code>libc++</code> 则需要 <code>13.3</code> 及以上）。</li><li><strong>跨平台一致的 <code>libc++</code></strong>：程序在 macOS、Linux 与 Windows 上使用的是同一套 <code>libc++</code> 实现。</li></ul><p>传入 <code>-stdlib=platform</code> 会切换到 <code>bin/&lt;triple&gt;-system.cfg</code>（<a href="./../reference/patches">补丁 0018</a>），保留 SDK、部署目标版本与 <code>ld64.lld</code>，并链接操作系统的 <code>/usr/lib/libc++.1.dylib</code>（<a href="./../guide/cross-compiling#the-platform-s-c-library">交叉编译</a>）。</p><p><code>x86_64-apple-darwin</code> 主机工具链本身是在 <code>arm64</code> macOS 上交叉编译出来的——构建时会先编译出 <code>arm64</code> 架构的表生成器（table generator），从而避免在构建过程中通过 Rosetta 运行任何 <code>x86_64</code> 程序——随后在 <code>x86_64</code> Mac（<code>macos-15-intel</code>）上完成测试。</p><h2 id="无需安装-xcode-获取-apple-sdk" tabindex="-1">无需安装 Xcode 获取 Apple SDK <a class="header-anchor" href="#无需安装-xcode-获取-apple-sdk" aria-label="Permalink to &quot;无需安装 Xcode 获取 Apple SDK&quot;">​</a></h2><p>Apple 的 macOS SDK 包含在 <code>swcdn.apple.com</code> 分发的 Command Line Tools <code>.pkg</code> 安装包内，列在无需 Apple ID 即可访问的 Apple 软件更新目录（<code>swscan.apple.com</code>）中。<code>.pkg</code> 是一个 <code>xar</code> 压缩包，其中的 <code>Payload</code> 是由多个 <code>xz</code> 分块组成的 <code>pbzx</code> 流，内部封装了一个 <code>cpio</code> 归档。<code>xclang</code> 使用自身代码直接解析 <code>xar</code>、<code>pbzx</code>、<code>xz</code> 和 <code>cpio</code>，因此 <code>xclang sdk fetch macos</code> 无需借助任何 macOS 专用工具即可在 Linux、Windows 和 macOS 上运行（<a href="./../reference/xclang-command"><code>xclang</code> 命令</a>）。</p><p>解压时，<code>xclang</code> 只提取 <code>Library/Developer/CommandLineTools/SDKs/MacOSX&lt;ver&gt;.sdk</code>，并跳过 <code>usr/bin/</code>、<code>usr/share/</code>（其中的 man 手册文件名含有 Windows 文件系统不允许的 <code>:</code> 字符）和 <code>System/Library/Perl/</code>。在 Windows 上，SDK 中的符号链接默认会创建为无需提权的目录联接（junction）和文件硬链接（<code>--links junction</code>）。</p><p><a href="./windows#config-files-and-object-directives">Windows MSVC 目标平台</a>需要通过生成的配置文件传入 MSVC 与 Windows SDK 的版本号子目录，而 macOS SDK 只需要指定根目录。因此 Linux 与 Windows 上的目标平台配置文件可以直接写入 <code>-isysroot &lt;CFGDIR&gt;/../sdk/macos</code>；即使工具链内尚未下载 SDK，在命令行显式传入 <code>-isysroot</code> 也依然可以正常工作。</p><h2 id="apple-下架安装包的处理与内容摘要" tabindex="-1">Apple 下架安装包的处理与内容摘要 <a class="header-anchor" href="#apple-下架安装包的处理与内容摘要" aria-label="Permalink to &quot;Apple 下架安装包的处理与内容摘要&quot;">​</a></h2><p>Apple 的软件更新目录列出了各个 macOS 版本当前可用的 Command Line Tools 安装包。Apple 会不定期下架旧安装包（在 <code>swcdn.apple.com</code> 上返回 <code>403</code> 或 <code>404</code>），并替换为重新签名的安装包——新安装包的外层压缩包字节发生了变化，但内部的 SDK 完全未变：例如当产品编号 <code>142-50405</code> 替换 <code>082-83364</code> 时，其中 macOS <code>26.5</code> SDK 的全部 18,516 个文件完全一致。</p><p>兼顾安装包下架容错与构建可复现性的做法是，<code>xclang/sdk-versions.json</code> 对每个 macOS 安装包做了双重锁定：同时记录外层 <code>.pkg</code> 压缩包的 <code>sha256</code> 以及内部 SDK 的内容摘要。当 Apple 的 CDN 对锁定的 URL 返回 <code>403</code> 或 <code>404</code> 时，<code>xclang sdk fetch</code>（以及 <a href="./../integrations/bazel">Bazel</a> 模块的回退逻辑）会读取 Apple 的更新目录，检查候选安装包 <code>Payload</code> 的开头部分以寻找所请求的 SDK 版本，并在解压后的 SDK 与锁定的内容摘要一致时接受这个安装包。</p><p>内容摘要是 SDK 清单的 <code>sha256</code> 值。这份清单涵盖安装包 <code>cpio</code> 载荷中 <code>Library/Developer/CommandLineTools/SDKs/MacOSX&lt;ver&gt;.sdk/</code> 下的每个普通文件与符号链接（包括 <code>xclang</code> 解压落盘时跳过的 man 手册、工具与 Perl 文件），按路径逐字节排序，每行一条记录：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>file &lt;sha256 of its bytes&gt; &lt;path&gt;</span></span>\n<span class="line"><span>link &lt;sha256 of its target&gt; &lt;path&gt;</span></span></code></pre></div><p>每行以换行符结尾，<code>&lt;path&gt;</code> 是使用 <code>/</code> 分隔的相对于 SDK 根目录的路径，硬链接则按普通 <code>file</code> 对其字节内容计算哈希。目录本身、文件权限、修改时间以及 <code>xclang</code> 在 Windows 上创建链接的方式均不影响摘要结果；在 Mac 上运行 <code>pkgutil --expand-full</code> 解压出的是同一棵目录树。</p><p>这种锁定机制带来四点直接影响：</p><ul><li><strong>Apple 已彻底下架的版本无法下载</strong>：当 Apple 在更新目录中用新版本替换了旧版本 SDK（例如用 <code>27.2</code> 替换 <code>27.0</code>）时，目录中不再有任何安装包包含旧版本，下载会报错退出并列出 Apple 当前提供的版本。</li><li><strong>相同的版本号字符串不代表同一个 SDK</strong>：早期 Command Line Tools 构建中的 <code>26.5</code> SDK 与锁定的 <code>26.5</code> 有 9 个文件不同；即使版本号字符串相同，只要 SDK 内容与锁定的摘要不符，安装包也会被拒绝。</li><li><strong><code>--version latest</code> 不可复现</strong>：它会直接采用运行时 Apple 更新目录中列出的最新 SDK，可能超出版本表范围且未经锁定。</li><li><strong>xclang 不维护镜像</strong>：xclang 不会在自己的服务器上缓存或二次分发 Apple 的安装包。将 <code>.pkg</code> 保存在 <code>xclang sdk fetch</code> 的 <code>--cache</code> 目录，或保存在 Bazel 的仓库缓存及 <code>--distdir</code> 中（<a href="./../integrations/ci">CI</a>），即可在 Apple 将对应版本从 CDN 移除后继续用于构建。</li></ul><h2 id="为什么使用-ld64-lld-与补丁-0007" tabindex="-1">为什么使用 <code>ld64.lld</code> 与补丁 0007 <a class="header-anchor" href="#为什么使用-ld64-lld-与补丁-0007" aria-label="Permalink to &quot;为什么使用 `ld64.lld` 与补丁 0007&quot;">​</a></h2><p>在 macOS、Linux 和 Windows 上统一使用 <code>ld64.lld</code>，不仅让所有主机拥有同一个 Mach-O 链接器，还能在不调用 <code>codesign</code> 的情况下对 <code>arm64</code> 二进制文件作临时签名，直接按编译器自身的 LLVM 版本支持 LTO（无需随附 120 MB 的 <code>libLTO.dylib</code> 或传入 <code>-lto_library</code>），并在所有主机上接受相同的 ThinLTO 缓存（<code>-cache_path_lto</code>）与相对路径调试映射表（<code>-oso_prefix</code>）参数。</p><p>当 <code>clang</code> 在单条命令中同时执行 ThinLTO 编译与链接时，会向链接器传入 <code>-object_path_lto</code>。启用 <code>-object_path_lto</code> 后，LTO 后端首先会写出一个空目标文件，其中唯一的符号 <code>ltmp0</code> 与紧随其后的函数（<code>main</code>）具有相同的地址。上游 <code>ld64.lld</code> 会从代码段的所有符号收集栈展开条目，导致在 <code>arm64</code> 上 <code>ltmp0</code> 的空展开条目覆盖了 <code>__unwind_info</code> 中 <code>main</code> 的条目，使异常无法穿过 <code>main</code> 展开（<code>llvm/llvm-project#224949</code>，已由 <code>llvm/llvm-project#225055</code> 修复）。xclang 通过<a href="./../reference/patches">补丁 0007</a> 合入了这项修复。</p><p>此外，Xcode 27 的 macOS 27 SDK 在 <code>libSystem</code> 及系统框架的 <code>.tbd</code> 桩文件中引入了新的架构名称 <code>arm64e.x1</code>，xclang 中的 LLVM TextAPI 已支持这一名称。</p><h2 id="mach-o-上的调试信息" tabindex="-1">Mach-O 上的调试信息 <a class="header-anchor" href="#mach-o-上的调试信息" aria-label="Permalink to &quot;Mach-O 上的调试信息&quot;">​</a></h2><p>Mach-O 链接会将 DWARF 调试信息保留在 <code>.o</code> 目标文件中，并在可执行文件的调试映射表（debug map，即 <code>N_OSO</code> stab 条目）里记录这些目标文件的路径，再由 <code>dsymutil</code> 根据它们收集生成 <code>.dSYM</code> 包（<a href="./../features/debugging">调试</a>）：</p><ul><li><strong>调试映射表中的相对路径</strong>：默认情况下，调试映射表记录的是各个目标文件的绝对路径，因此在不同目录下链接同一个程序会生成不同的字节内容。Bazel 链接时会传入 <code>-oso_prefix .</code>，使调试映射表记录形如 <code>bazel-out/...</code> 的相对路径。</li><li><strong>ThinLTO 临时目标文件</strong>：启用 ThinLTO 时，LTO 后端生成的临时目标文件会在链接结束时被链接器删除，因此 xclang 的 <a href="./../integrations/cmake">CMake</a> 与 <a href="./../integrations/bazel">Bazel</a> 集成会传入 <code>-object_path_lto</code>，并在链接步骤中一并生成 <code>.dSYM</code> 包（<a href="./../features/debugging#why-a-dsym-comes-from-the-link">为什么在链接阶段生成 dSYM</a>）。</li><li><strong>剥离符号</strong>：发布二进制文件使用与 Apple 的 <code>strip</code> 行为一致的 <code>llvm-strip --strip-all</code> 剥离符号；优化版 Bazel 构建还会传入 <code>-Wl,-no_exported_symbols</code>，使剥离符号后的可执行文件不保留任何导出的弱 C++ 符号，防止 <code>dladdr</code> 将崩溃栈帧误归因到这些符号上（<a href="./../features/debugging#strip">剥离符号</a>）。</li></ul><h2 id="sanitizer-的-dylib" tabindex="-1">Sanitizer 的 dylib <a class="header-anchor" href="#sanitizer-的-dylib" aria-label="Permalink to &quot;Sanitizer 的 dylib&quot;">​</a></h2><p>两个 macOS 目标平台均支持 AddressSanitizer（附带经 ASan 插桩的 <code>libc++</code>）、ThreadSanitizer、LeakSanitizer、UndefinedBehaviorSanitizer 与 libFuzzer。它们的运行时库是位于 <code>lib/clang/&lt;major&gt;/lib/darwin/</code> 下的通用二进制 <code>.dylib</code> 文件（<code>libclang_rt.*_osx_dynamic.dylib</code>），在运行时从工具链或可执行文件所在目录加载，属于仅供测试使用的<a href="./hermeticity">封闭性</a>例外（<a href="./../features/sanitizers">sanitizer</a>）。在构建 xclang 工具链时，面向 Darwin 的 <code>compiler-rt</code> 会带 <code>ZERO_AR_DATE=1</code> 链接，避免静态库归档的时间戳写入 <code>.dylib</code> 的调试映射表或 Mach-O UUID。</p>',29)])])}const h=c(l,[["render",i]]);export{m as __pageData,h as default};
